--!strict
-- Lives in Crate.prefab: tags its entity in OnCreate and keeps a reference to the prefab's Lid, which every instance
-- remaps to its own member (§5.5).
export type Tagger = ScriptInstance & {
	Tag: string,
	Lid: Entity?,
	CreatedTick: number,
}

local Tagger = {}

Tagger.Fields = {
	Tag = Field.String("Tagged"),
	Lid = Field.Entity(),
}

function Tagger.OnCreate(self: Tagger)
	self.Entity:AddTag(self.Tag)
	self.CreatedTick = Time.GetTick()
end

return Script.Define("Tagger", Tagger)

--!strict
-- References into prefab instances from outside them: an instance root, a member of it and the prefab asset to spawn
-- more from (Prefabs.scene's Inspector).
export type Linked = ScriptInstance & {
	Crate: Entity?,
	Target: Entity?,
	Spawnable: AssetRef?,
}

local Linked = {}

Linked.Fields = {
	Crate = Field.Entity(),
	Target = Field.Entity(),
	Spawnable = Field.Asset("Prefab"),
}

return Script.Define("Linked", Linked)
